// 十神速查表: [日干][比较干] -> { name, type }
// 华山规则: 正财=财, 偏财=才 (与传统相反)
const SHI_SHEN_TABLE = (function() {
  const tg = TIANGAN;
  const table = {};
  for (let i = 0; i < 10; i++) {
    table[tg[i]] = {};
    for (let j = 0; j < 10; j++) {
      const rel = (j - i + 10) % 10;
      const sameYinYang = (i % 2) === (j % 2);
      let name;
      // rel: 0=同我, 1=我生, 2=我生, 3=我生?, ...
      // 五行关系: 同我(比劫), 我生(食伤), 我克(财), 克我(官杀), 生我(印)
      // 用五行来确定关系
      const wx_i = '木木火火土土金金水水'[i];
      const wx_j = '木木火火土土金金水水'[j];
      // 生克序列: 木火土金水
      const wxOrder = '木火土金水';
      const idxI = wxOrder.indexOf(wx_i);
      const idxJ = wxOrder.indexOf(wx_j);
      const diff = (idxJ - idxI + 5) % 5;
      // diff: 0=同, 1=我生, 2=我克, 3=克我, 4=生我
      if (diff === 0) name = sameYinYang ? '比肩' : '劫财';
      else if (diff === 1) name = sameYinYang ? '食神' : '伤官';
      else if (diff === 2) name = sameYinYang ? '偏财' : '正财';
      else if (diff === 3) name = sameYinYang ? '七杀' : '正官';
      else if (diff === 4) name = sameYinYang ? '偏印' : '正印';
      table[tg[i]][tg[j]] = name;
    }
  }
  return table;
})();

