// Helper: convert Gregorian date to lunar date
function gregToLunar(year, month, day) {
  const data = LUNAR_DATA[year];
  if (!data) return { lyear: year, lmonth: month, lday: day, isLeap: false };
  const birthDOY = daysBetween(year, 1, 1, year, month, day);
  if (birthDOY < data.lnyDOY) {
    const prevData = LUNAR_DATA[year - 1];
    if (!prevData) return { lyear: year, lmonth: month, lday: day, isLeap: false };
    const prevYearEnd = daysBetween(year - 1, 1, 1, year - 1, 12, 31);
    let daysFromPrevLNY = (prevYearEnd - prevData.lnyDOY) + birthDOY + 1;
    let lm = 0, ld = 0, isLeap = false;
    for (let i = 0; i < prevData.months.length; i++) {
      const len = prevData.months[i];
      if (daysFromPrevLNY <= len) { lm = i + 1; ld = daysFromPrevLNY; if (prevData.leap > 0 && lm > prevData.leap) lm--; if (prevData.leap > 0 && lm === prevData.leap && i >= prevData.leap) isLeap = true; break; }
      daysFromPrevLNY -= len;
    }
    if (lm === 0) { lm = 12; ld = daysFromPrevLNY || 30; }
    ld = Math.min(ld + 1, 30);
    return { lyear: year - 1, lmonth: lm, lday: ld || 1, isLeap: isLeap };
  } else {
    let daysFromLNY = birthDOY - data.lnyDOY + 1;
    let lm = 0, ld = 0, isLeap = false;
    for (let i = 0; i < data.months.length; i++) {
      const len = data.months[i];
      if (daysFromLNY <= len) { lm = i + 1; ld = daysFromLNY; if (data.leap > 0 && lm > data.leap) lm--; if (data.leap > 0 && lm === data.leap && i >= data.leap) isLeap = true; break; }
      daysFromLNY -= len;
    }
    if (lm === 0) { lm = 12; ld = daysFromLNY || 30; }
    ld = Math.min(ld + 1, 30);
    return { lyear: year, lmonth: lm || 1, lday: ld || 1, isLeap: isLeap };
  }
}